protected void new()
{
    super(classStr(AVAGAEBExportD94Service), methodStr(AVAGAEBExportD94Service, process), SysOperationExecutionMode::Synchronous);
}

public static AVAGAEBExportD94Controller construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAGAEBExportD94Controller controller;
    controller = new AVAGAEBExportD94Controller();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVAGAEBExportD94Controller  controller;
    SysOperationStartResult     sysOperationStartResult;
    AVAGAEBExportD94Contract    dataContract;
    Set                         recordSet;
    MultiSelectionHelper        multiselectionHelper;
    SalesQuotationTable         sql;

    controller = AVAGAEBExportD94Controller::construct();
    controller.parmArgs(_args);

    if (_args && _args.caller() is FormRun)
    {
        recordSet = new Set(Types::Record);
        multiselectionHelper = MultiSelectionHelper::createFromCaller(_args.caller());

        sql = multiselectionHelper.getFirst();
        while (sql)
        {
            recordSet.add(sql);

            sql = multiselectionHelper.getNext();
        }
    }

    dataContract = controller.getDataContractObject();
    if (dataContract is AVAGAEBExportD94Contract)
    {
        dataContract.parmRecordCon(recordSet.pack());
    }

    sysOperationStartResult = controller.startOperation();
}

